CREATE TABLE IF NOT EXISTS acquirer_limit_rules (id VARCHAR(64) PRIMARY KEY, scope_type VARCHAR(32) NOT NULL, scope_id VARCHAR(128) NOT NULL, transaction_type VARCHAR(64) NOT NULL, maximum_amount_minor BIGINT NOT NULL, enabled BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS developer_organizations (id VARCHAR(64) PRIMARY KEY, name VARCHAR(256) NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS developer_apps (id VARCHAR(64) PRIMARY KEY, organization_id VARCHAR(64) NOT NULL, name VARCHAR(256) NOT NULL, status VARCHAR(32) NOT NULL, scopes VARCHAR(2000) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS developer_credentials (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, client_id VARCHAR(128) NOT NULL, secret_reference VARCHAR(512) NOT NULL, revoked BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS developer_certificates (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, thumbprint VARCHAR(256) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS developer_webhooks (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, url VARCHAR(2000) NOT NULL, events VARCHAR(2000) NOT NULL, signing_key_reference VARCHAR(512) NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS developer_api_logs (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, event_type VARCHAR(64) NOT NULL, detail VARCHAR(1000) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS developer_certification (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL UNIQUE, application_profile VARCHAR(32) NOT NULL, security_review VARCHAR(32) NOT NULL, sandbox_tests VARCHAR(32) NOT NULL, aps_approval VARCHAR(32) NOT NULL, operations_approval VARCHAR(32) NOT NULL, production_credentials VARCHAR(32) NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id VARCHAR(64) PRIMARY KEY, webhook_id VARCHAR(64) NOT NULL, event_id VARCHAR(128) NOT NULL, event_type VARCHAR(128) NOT NULL, status VARCHAR(32) NOT NULL, attempts INTEGER NOT NULL, next_attempt_at TIMESTAMP NOT NULL, last_http_status INTEGER, created_at TIMESTAMP NOT NULL);
